package li.cil.oc.server.component;

import li.cil.oc.Settings;
import li.cil.oc.api.driver.DeviceInfo;
import li.cil.oc.api.internal.Database;
import li.cil.oc.api.machine.*;
import li.cil.oc.api.network.*;
import li.cil.oc.api.prefab.ItemStackArrayValue;
import li.cil.oc.util.*;
import net.minecraft.core.Direction;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.world.item.ItemStack;
import net.neoforged.neoforge.fluids.capability.IFluidHandler;
import net.neoforged.neoforge.items.IItemHandler;
import java.util.*;
import java.util.function.Function;

/** Inventory and tank analytics plus powered, simulated-before-execute transfers. */
public class Transposer extends WorldComponent implements DeviceInfo {
    public interface ActivityHost {void onTransposerActivity();}
    public Transposer(EnvironmentHost host){super(host);setNode(li.cil.oc.api.Network.newNode(this,Visibility.Network).withComponent("transposer").withConnector().create());}
    @Override protected Direction side(Arguments args,int index){int value=args.checkInteger(index);if(value<0||value>5)throw new IllegalArgumentException("invalid side");return Direction.from3DDataValue(value);}
    @Override public Map<String,String> getDeviceInfo(){return Map.of("class","generic","description","Transposer","vendor","MightyPirates GmbH & Co. KG","product","TP4k-iX");}
    private Object[] inventory(Arguments args,Function<IItemHandler,Object[]> action){Direction direction=side(args,0);var source=InventoryUtils.inventorySourceAt(host.world(),position().relative(direction),direction.getOpposite());return source.isPresent()&&mayInteract(source.get())?action.apply(source.get().inventory()):new Object[]{null,"no inventory"};}
    private IItemHandler inventory(Direction direction){var source=InventoryUtils.inventorySourceAt(host.world(),position().relative(direction),direction.getOpposite());if(source.isEmpty()||!mayInteract(source.get()))return null;return source.get().inventory();}
    private Database database(String address){Node target=node().network()==null?null:node().network().node(address);if(target==null||!target.canBeReachedFrom(node()))throw new IllegalArgumentException("no such component");if(!(target.host() instanceof Database database))throw new IllegalArgumentException("not a database");return database;}
    private boolean transferEnergy(){boolean result=((Connector)node()).tryChangeBuffer(-Settings.get().transposerCost);if(result&&host instanceof ActivityHost activity)activity.onTransposerActivity();return result;}
    @Callback(doc="function(side:number):number -- Get the number of inventory slots.") public Object[] getInventorySize(Context context,Arguments args){return inventory(args,handler->new Object[]{handler.getSlots()});}
    @Callback(doc="function(side:number,slot:number):number -- Get the stack size in a slot.") public Object[] getSlotStackSize(Context context,Arguments args){return inventory(args,handler->new Object[]{handler.getStackInSlot(slot(args,1,handler.getSlots())).getCount()});}
    @Callback(doc="function(side:number,slot:number):number -- Get the maximum stack size in a slot.") public Object[] getSlotMaxStackSize(Context context,Arguments args){return inventory(args,handler->{ItemStack stack=handler.getStackInSlot(slot(args,1,handler.getSlots()));return new Object[]{stack.isEmpty()?0:stack.getMaxStackSize()};});}
    @Callback(doc="function(side:number,slotA:number,slotB:number[,checkNBT:boolean]):boolean -- Compare two item stacks.") public Object[] compareStacks(Context context,Arguments args){return inventory(args,handler->{ItemStack a=handler.getStackInSlot(slot(args,1,handler.getSlots())),b=handler.getStackInSlot(slot(args,2,handler.getSlots()));return new Object[]{a==b||InventoryUtils.haveSameItemType(a,b,args.optBoolean(3,false))};});}
    @Callback(doc="function(side:number,slot:number,dbAddress:string,dbSlot:number[,checkNBT:boolean]):boolean -- Compare a stack to a database entry.") public Object[] compareStackToDatabase(Context context,Arguments args){return inventory(args,handler->{Database database=database(args.checkString(2));return new Object[]{InventoryUtils.haveSameItemType(handler.getStackInSlot(slot(args,1,handler.getSlots())),Objects.requireNonNullElse(database.getStackInSlot(slot(args,3,database.size())),ItemStack.EMPTY),args.optBoolean(4,false))};});}
    @Callback(doc="function(side:number,slotA:number,slotB:number):boolean -- Check whether two stacks share an item tag.") public Object[] areStacksEquivalent(Context context,Arguments args){return inventory(args,handler->{ItemStack a=handler.getStackInSlot(slot(args,1,handler.getSlots())),b=handler.getStackInSlot(slot(args,2,handler.getSlots()));return new Object[]{a==b||!a.isEmpty()&&!b.isEmpty()&&a.getTags().anyMatch(b::is)};});}
    @Callback(doc="function(side:number,slot:number):table -- Inspect a stack.") public Object[] getStackInSlot(Context context,Arguments args){return Settings.get().allowItemStackInspection?inventory(args,handler->new Object[]{handler.getStackInSlot(slot(args,1,handler.getSlots())).copy()}):new Object[]{null,"not enabled in config"};}
    @Callback(doc="function(side:number):userdata -- Inspect all stacks.") public Object[] getAllStacks(Context context,Arguments args){return Settings.get().allowItemStackInspection?inventory(args,handler->{ItemStack[] stacks=new ItemStack[handler.getSlots()];for(int i=0;i<stacks.length;i++)stacks[i]=handler.getStackInSlot(i).copy();return new Object[]{new ItemStackArrayValue(stacks,host.world().registryAccess())};}):new Object[]{null,"not enabled in config"};}
    @Callback(doc="function(side:number):string -- Get the inventory registry name.") public Object[] getInventoryName(Context context,Arguments args){if(!Settings.get().allowItemStackInspection)return new Object[]{null,"not enabled in config"};Direction side=side(args,0);var source=InventoryUtils.inventorySourceAt(host.world(),position().relative(side),side.getOpposite());if(source.isEmpty()||!mayInteract(source.get()))return new Object[]{null,"no inventory"};return new Object[]{source.get() instanceof InventoryUtils.BlockInventorySource block?BuiltInRegistries.BLOCK.getKey(host.world().getBlockState(block.position()).getBlock()).toString():BuiltInRegistries.ENTITY_TYPE.getKey(((InventoryUtils.EntityInventorySource)source.get()).entity().getType()).toString()};}
    @Callback(doc="function(side:number,slot:number,dbAddress:string,dbSlot:number):boolean -- Store a stack in a database.") public Object[] store(Context context,Arguments args){return inventory(args,handler->{Database database=database(args.checkString(2));int to=slot(args,3,database.size());ItemStack old=database.getStackInSlot(to);database.setStackInSlot(to,handler.getStackInSlot(slot(args,1,handler.getSlots())).copy());return new Object[]{old!=null&&!old.isEmpty()};});}
    @Callback(doc="function(sourceSide:number,sinkSide:number[,count:number,sourceSlot:number,sinkSlot:number]):number -- Transfer items between inventories.") public Object[] transferItem(Context context,Arguments args){
        Direction from=side(args,0),to=side(args,1);int count=Math.max(0,Math.min(64,args.optInteger(2,64)));if(!transferEnergy())return new Object[]{null,"not enough energy"};IItemHandler source=inventory(from),sink=inventory(to);if(source==null||sink==null)return new Object[]{null,"no inventory"};
        int moved=args.count()>3?InventoryUtils.transferBetweenInventoriesSlots(source,slot(args,3,source.getSlots()),sink,args.count()>4?slot(args,4,sink.getSlots()):null,count):InventoryUtils.transferBetweenInventories(source,sink,count);return new Object[]{moved};
    }
    @Callback(doc="function(sourceSide:number,sinkSide:number[,count:number,sourceTank:number]):boolean,number -- Transfer fluid between tanks.") public Object[] transferFluid(Context context,Arguments args){Direction from=side(args,0),to=side(args,1);int count=Math.max(0,args.optInteger(2,1000));if(!transferEnergy())return new Object[]{null,"not enough energy"};int moved=FluidUtils.transferBetweenFluidHandlersAt(host.world(),position().relative(from),from.getOpposite(),position().relative(to),to.getOpposite(),count,args.optInteger(3,-1));if(moved>0&&Settings.get().transposerFluidTransferRate>0)context.pause((double)moved/Settings.get().transposerFluidTransferRate);return new Object[]{moved>0,moved};}
    private Object[] tank(Arguments args,Function<IFluidHandler,Object[]> action){Direction direction=side(args,0);return FluidUtils.fluidHandlerAt(host.world(),position().relative(direction),direction.getOpposite()).map(action).orElseGet(()->new Object[]{null,"no tank"});}
    private int[] tanks(Arguments args,IFluidHandler handler){if(defined(args,1))return new int[]{slot(args,1,handler.getTanks())};int[] result=new int[handler.getTanks()];for(int i=0;i<result.length;i++)result[i]=i;return result;}
    @Callback(doc="function(side:number[,tank:number]):number -- Get stored fluid amount.") public Object[] getTankLevel(Context context,Arguments args){return tank(args,handler->{int total=0;for(int index:tanks(args,handler))total+=handler.getFluidInTank(index).getAmount();return new Object[]{total};});}
    @Callback(doc="function(side:number[,tank:number]):number -- Get tank capacity.") public Object[] getTankCapacity(Context context,Arguments args){return tank(args,handler->{int capacity=0;for(int index:tanks(args,handler))capacity=Math.max(capacity,handler.getTankCapacity(index));return new Object[]{capacity};});}
    private Map<String,Object> fluid(IFluidHandler handler,int tank){var fluid=handler.getFluidInTank(tank);Map<String,Object> result=new HashMap<>();result.put("capacity",handler.getTankCapacity(tank));result.put("amount",fluid.getAmount());if(!fluid.isEmpty()){result.put("hasTag",!fluid.getComponentsPatch().isEmpty());result.put("name",BuiltInRegistries.FLUID.getKey(fluid.getFluid()).toString());result.put("label",fluid.getHoverName().getString());}return result;}
    @Callback(doc="function(side:number[,tank:number]):table -- Inspect tank contents.") public Object[] getFluidInTank(Context context,Arguments args){if(!Settings.get().allowItemStackInspection)return new Object[]{null,"not enabled in config"};return tank(args,handler->{int[] selected=tanks(args,handler);if(defined(args,1))return new Object[]{fluid(handler,selected[0])};Object[] values=new Object[selected.length];for(int i=0;i<selected.length;i++)values[i]=fluid(handler,selected[i]);return new Object[]{values};});}
    @Callback(doc="function(side:number):number -- Get the number of tanks.") public Object[] getTankCount(Context context,Arguments args){return tank(args,handler->new Object[]{handler.getTanks()});}
    public static final class Upgrade extends Transposer {public Upgrade(EnvironmentHost host){super(host);((li.cil.oc.api.network.Component)node()).setVisibility(Visibility.Neighbors);}}
}
